gaq6(){return"\u0110\xe2y ch\u1ec9 l\xe0 bi\xean nh\u1eadn, kh\xf4ng t\u1ea3i l\u1ea1i \u1ea3nh ho\u1eb7c gia h\u1ea1n chia s\u1ebb."},
ga1v(){return"Ki\u1ec3m tra bi\xean nh\u1eadn \u1ea3nh"},
gaqc(){return"Ki\u1ec3m tra \u1ea3nh hi\u1ec7n h\xe0nh v\xe0 c\xe1c l\u1ea7n g\u1eedi c\xf2n ghi tr\xean thi\u1ebft b\u1ecb. M\xe3 g\u1eedi kh\xf4ng t\xecm th\u1ea5y v\u1eabn \u0111\u01b0\u1ee3c gi\u1eef \u0111\u1ec3 ki\u1ec3m tra l\u1ea1i. Kh\xf4ng t\u1ef1 g\u1eedi l\u1ea1i \u1ea3nh. Ch\u1ec9 t\xe0i kho\u1ea3n \u0111\u0103ng nh\u1eadp th\u01b0\u1eddng m\u1edbi b\u1ecf \u0111\u01b0\u1ee3c m\xe3 c\xf3 bi\xean nh\u1eadn \u0111\xe3 g\u1ee1 ho\u1eb7c h\u1ebft h\u1ea1n."},
gaq8(){return"M\xe3 OTP ch\u1ec9 cho \u0111\u1ecdc tr\u1ea1ng th\xe1i \u1ea3nh c\u1ee7a b\u1ea1n; kh\xf4ng \u0111\u0103ng nh\u1eadp, g\u1eedi \u1ea3nh ho\u1eb7c duy\u1ec7t \u1ea3nh."},
gaqb(){return"Ch\u01b0a t\xecm th\u1ea5y bi\xean nh\u1eadn \u1ea3nh. C\xf3 th\u1ec3 th\u1eed ki\u1ec3m tra l\u1ea1i sau; d\u1eef li\u1ec7u ch\u01b0a r\xf5 k\u1ebft qu\u1ea3 v\u1eabn \u0111\u01b0\u1ee3c gi\u1eef."},
gaqe(){return"B\u1ecf m\xe3 g\u1eedi \u0111\xe3 kh\xe9p kh\u1ecfi thi\u1ebft b\u1ecb"},
